from __future__ import annotations

import asyncio
import sys
from datetime import UTC, datetime
from pathlib import Path
from typing import Any

# Make the repo root importable when running from a source checkout.
_REPO_ROOT = Path(__file__).resolve().parents[1]
if str(_REPO_ROOT) not in sys.path:
    sys.path.insert(0, str(_REPO_ROOT))

from actor_factory.runner import ActorRunConfig, PPEScraperRunner  # noqa: E402

REPORT_TYPES = (
    "full",
    "odds_only",
    "sharp_only",
    "props_only",
    "live_only",
    "weather_only",
)


def _kelly_stakes(ev_items: list[dict[str, Any]]) -> dict[str, Any]:
    """Compute fractional Kelly stake sizing from +EV opportunities.

    Each +EV item must carry ``edge_pct`` (expected value %) and
    ``decimal_odds``. Full Kelly f = edge / (odds - 1); half and quarter
    Kelly are the conservative fractions most bettors actually use.
    """
    stakes: list[dict[str, Any]] = []
    for item in ev_items:
        edge = item.get("edge_pct")
        odds = item.get("decimal_odds")
        if not isinstance(edge, (int, float)) or not isinstance(odds, (int, float)):
            continue
        if odds <= 1.0 or edge <= 0:
            continue
        full_kelly = edge / 100.0 / (odds - 1.0)
        stakes.append(
            {
                "selection": item.get("selection") or item.get("market") or "unknown",
                "decimal_odds": odds,
                "edge_pct": edge,
                "full_kelly_pct": round(full_kelly * 100, 4),
                "half_kelly_pct": round(full_kelly * 50, 4),
                "quarter_kelly_pct": round(full_kelly * 25, 4),
            }
        )
    return {"opportunities": stakes, "count": len(stakes)}


async def _guarded(coro: Any) -> Any:
    """Await a data call; a failure degrades to None, never kills the run."""
    try:
        return await coro
    except Exception:  # noqa: BLE001 - per-section degradation by design
        return None


async def _sharp_block(
    item: dict[str, Any], sport: str, report_type: str, want: bool, options: dict[str, Any]
) -> None:
    from pry.api.routers.data.sports_data import (
        sports_alerts,
        sports_arbitrage,
        sports_betting_percentages,
        sports_plus_ev,
        sports_sharp_consensus,
    )

    enabled = options.get("include_sharp_intel", True) and (
        want or report_type == "sharp_only"
    )
    if not enabled:
        item["arbitrage"], item["ev"], item["sharp_intel"] = [], [], {}
        return
    arb_res, ev_res, pct_res, cons_res, alert_res = await asyncio.gather(
        _guarded(sports_arbitrage(sport=sport, min_yield_pct=0.5)),
        _guarded(sports_plus_ev(sharp_book="pinnacle", min_ev_pct=1.0)),
        _guarded(sports_betting_percentages(sport=sport, limit=50)),
        _guarded(sports_sharp_consensus(sport=sport, limit=50)),
        _guarded(sports_alerts(sport=sport, limit=50)),
    )
    item["arbitrage"] = (arb_res or {}).get("data", [])
    item["ev"] = (ev_res or {}).get("data", [])
    item["sharp_intel"] = {
        "betting_percentages": (pct_res or {}).get("data", []),
        "sharp_consensus": (cons_res or {}).get("data", []),
        "alerts": (alert_res or {}).get("data", []),
    }

async def _props_block(
    item: dict[str, Any], sport: str, report_type: str, want: bool
) -> None:
    if not (want or report_type == "props_only"):
        item["props"] = []
        return
    from pry.api.routers.data.sports_data import sports_props

    result = await _guarded(sports_props(player="", sport=sport, market=""))
    item["props"] = (result or {}).get("data", [])

async def _live_block(
    item: dict[str, Any], sport: str, report_type: str, want: bool
) -> None:
    if not (want or report_type == "live_only"):
        item["live_state"] = {}
        return
    from pry.api.routers.data.sports_data import sports_live_odds

    result = await _guarded(sports_live_odds(sport=sport, limit=50))
    item["live_state"] = (result or {}).get("data", [])


class BettingIntelRunner(PPEScraperRunner):
    """Runner that maps one URL to a full betting-intelligence report."""

    async def process_url(self, url: str, options: dict[str, Any]) -> dict[str, Any]:
        from pry.api.routers.data.sports_data import (
            sports_books,
            sports_odds,
        )

        report_type = options.get("report_type", "full")
        if report_type not in REPORT_TYPES:
            report_type = "full"
        sport = options.get("sport", "all") or "all"
        want = report_type == "full"

        item: dict[str, Any] = {
            "url": url,
            "status": "ok",
            "report_type": report_type,
            "sport": sport,
            "scraped_at": datetime.now(UTC).isoformat(),
        }

        # Odds + books are the base layer for every report type.
        odds_task = _guarded(sports_odds(event_query="", sport=sport, limit=50))
        books_task = _guarded(sports_books(sport=sport, market="h2h", limit=50))
        odds_res, books_res = await asyncio.gather(odds_task, books_task)
        item["odds"] = {
            "events": (odds_res or {}).get("data", []),
            "books_registry": (books_res or {}).get("data", []),
        }

        await _sharp_block(item, sport, report_type, want, options)
        await _props_block(item, sport, report_type, want)
        await _live_block(item, sport, report_type, want)
        weather_on = options.get("include_weather", True) and (
            want or report_type == "weather_only"
        )
        item["weather"] = {"available": False, "assessment": None} if weather_on else {}
        pred_on = want and options.get("include_prediction_markets", True)
        item["prediction_markets"] = (
            {"available": False, "cross_reference": []} if pred_on else {}
        )
        item["kelly_sizing"] = (
            _kelly_stakes(item["ev"])
            if want and options.get("include_kelly", True)
            else {}
        )
        item["metadata"] = {
            "domain": url.split("/")[2] if "://" in url else url,
            "report_type": report_type,
            "sport": sport,
        }
        return item


async def main() -> None:
    runner = BettingIntelRunner(
        config=ActorRunConfig(
            primary_event="betting-intel-generated",
            default_output_format="markdown",
            processor_name="jsondata",
        ),
        actor_module=None,  # resolved lazily so tests can inject a mock
    )
    await runner.run()


if __name__ == "__main__":
    asyncio.run(main())
